To create a debounced asynchronous API call function with cancellation support in JavaScript, you can use the following approach. This function will ensure that the API call is only made after a specified delay and will cancel any ongoing requests if a new request is initiated within the delay period.

Here's a sample implementation:

```javascript
function debounceAsync(apiCall, delay) {
    let timeoutId;
    let controller;

    return function (...args) {
        // Clear the existing timeout
        if (timeoutId) {
            clearTimeout(timeoutId);
        }

        // If there is an ongoing request, abort it
        if (controller) {
            controller.abort();
        }

        // Create a new AbortController for the new request
        controller = new AbortController();
        const signal = controller.signal;

        // Set a new timeout for the API call
        timeoutId = setTimeout(async () => {
            try {
                const result = await apiCall(...args, { signal });
                console.log('API call result:', result);
            } catch (error) {
                if (error.name === 'AbortError') {
                    console.log('API call was aborted');
                } else {
                    console.error('Error making API call:', error);
                }
            } finally {
                // Clean up
                timeoutId = null;
                controller = null;
            }
        }, delay);
    };
}

